<script setup lang="ts">
import type { CrmSalesOrderListItemDto, CrmSalesOrderLineDto } from '@/api'
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { createPageRequest, CrmSalesOrderStatus, crmSalesOrderApi } from '@/api'
import { toast } from '~/composables'
import { usePermission } from '~/hooks'
defineOptions({ name: 'CrmSalesOrderPage' })
const { t } = useI18n(); const { hasPermission } = usePermission()
const rows=ref<CrmSalesOrderListItemDto[]>([]); const lines=ref<CrmSalesOrderLineDto[]>([]); const loading=ref(false); const keyword=ref(''); const status=ref<CrmSalesOrderStatus|''>(''); const pageIndex=ref(1); const totalCount=ref(0); const pageSize=20; const selected=ref<CrmSalesOrderListItemDto|null>(null)
const totalPages=computed(()=>Math.max(1,Math.ceil(totalCount.value/pageSize))); const canExecute=computed(()=>hasPermission('crm_sales_orders.execute'))
async function loadPage(){loading.value=true;try{const p=createPageRequest({page:{pageIndex:pageIndex.value,pageSize}});const r=await crmSalesOrderApi.page({...p,keyword:keyword.value.trim()||null,status:status.value===''?null:status.value});rows.value=r.items;totalCount.value=r.page.totalCount}catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.loadError'))}finally{loading.value=false}}
async function openLines(row:CrmSalesOrderListItemDto){selected.value=row;try{const p=createPageRequest({page:{pageIndex:1,pageSize:100}});const r=await crmSalesOrderApi.lines({...p,salesOrderId:row.basicId});lines.value=r.items}catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.linesError'))}}
async function changeStatus(row:CrmSalesOrderListItemDto,next:CrmSalesOrderStatus){try{await crmSalesOrderApi.changeStatus({id:row.basicId,status:next});toast.success(t('crm.salesOrder.statusSaved'));await loadPage()}catch(e){toast.danger((e as Error)?.message||t('crm.salesOrder.statusError'))}}
function label(s:number){return t(`crm.salesOrder.status${s}`)}
onMounted(loadPage)
</script>
<template><main class="crm-workflow-page"><header class="page-header"><div><h1>{{t('crm.salesOrder.title')}}</h1><p>{{t('crm.salesOrder.description')}}</p></div></header><section class="toolbar"><input v-model="keyword" :placeholder="t('crm.salesOrder.search')" @keydown.enter="pageIndex=1;loadPage()"><select v-model="status"><option value="">{{t('crm.salesOrder.allStatuses')}}</option><option v-for="s in [0,1,2,3,4,5]" :key="s" :value="s">{{label(s)}}</option></select><button @click="pageIndex=1;loadPage()">{{t('crm.salesOrder.query')}}</button><button :disabled="loading" @click="loadPage">{{t('crm.salesOrder.refresh')}}</button></section><section class="table-wrap"><div v-if="loading&&!rows.length" class="empty">{{t('crm.salesOrder.loading')}}</div><div v-else-if="!rows.length" class="empty">{{t('crm.salesOrder.empty')}}</div><table v-else><thead><tr><th>{{t('crm.salesOrder.number')}}</th><th>{{t('crm.salesOrder.customer')}}</th><th>{{t('crm.salesOrder.date')}}</th><th>{{t('crm.salesOrder.status')}}</th><th>{{t('crm.salesOrder.total')}}</th><th>{{t('crm.salesOrder.actions')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.basicId"><td>{{row.orderNumber}}</td><td>{{row.customerNameSnapshot}} (#{{row.customerId}})</td><td>{{new Date(row.orderDate).toLocaleDateString()}</td><td>{{label(row.status)}}</td><td>{{row.grandTotal.toLocaleString()}} {{row.currency}}</td><td class="actions"><button @click="openLines(row)">{{t('crm.salesOrder.viewLines')}}</button><button v-if="canExecute&&row.status===CrmSalesOrderStatus.Draft" @click="changeStatus(row,CrmSalesOrderStatus.Confirmed)">{{t('crm.salesOrder.confirm')}}</button><button v-if="canExecute&&row.status===CrmSalesOrderStatus.Confirmed" @click="changeStatus(row,CrmSalesOrderStatus.Processing)">{{t('crm.salesOrder.start')}}</button><button v-if="canExecute&&row.status===CrmSalesOrderStatus.Draft" @click="changeStatus(row,CrmSalesOrderStatus.Cancelled)">{{t('crm.salesOrder.cancelOrder')}}</button></td></tr></tbody></table></section><footer class="pagination"><span>{{t('crm.salesOrder.total',{count:totalCount})}} · {{t('crm.salesOrder.page',{current:pageIndex,total:totalPages})}}</span><div><button :disabled="pageIndex<=1||loading" @click="pageIndex--;loadPage()">{{t('crm.salesOrder.previous')}}</button><button :disabled="pageIndex>=totalPages||loading" @click="pageIndex++;loadPage()">{{t('crm.salesOrder.next')}}</button></div></footer><div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="editor"><header><h2>{{selected.orderNumber}} · {{t('crm.salesOrder.lines')}}</h2><button @click="selected=null">×</button></header><p>{{selected.customerNameSnapshot}} · {{label(selected.status)}}</p><div class="table-wrap"><table><thead><tr><th>{{t('crm.salesOrder.product')}}</th><th>{{t('crm.salesOrder.quantity')}}</th><th>{{t('crm.salesOrder.reserved')}}</th><th>{{t('crm.salesOrder.shipped')}}</th><th>{{t('crm.salesOrder.remaining')}}</th></tr></thead><tbody><tr v-for="line in lines" :key="line.basicId"><td>{{line.productCode||line.description}}</td><td>{{line.quantity}}</td><td>{{line.reservedQuantity}}</td><td>{{line.shippedQuantity}}</td><td>{{line.remainingQuantity}}</td></tr></tbody></table></div></section></div></main></template>
<style scoped>
.crm-workflow-page{display:flex;flex-direction:column;gap:16px;min-height:100%;padding:20px;color:hsl(var(--foreground))}.page-header,.toolbar,.pagination,.editor header{display:flex;align-items:center;justify-content:space-between;gap:12px}.page-header h1,.editor h2{margin:0;font-size:20px}.page-header p{margin:5px 0 0;color:hsl(var(--muted-foreground));font-size:12px}button,input,select{font:inherit}button{border:1px solid hsl(var(--border));border-radius:7px;padding:7px 11px;background:hsl(var(--card));cursor:pointer}.toolbar{justify-content:flex-start;flex-wrap:wrap}.toolbar input,.toolbar select{border:1px solid hsl(var(--border));border-radius:7px;padding:8px 10px;background:hsl(var(--card));color:inherit}.table-wrap{overflow:auto;border:1px solid hsl(var(--border));border-radius:10px;background:hsl(var(--card))}table{width:100%;border-collapse:collapse;min-width:760px;text-align:left;font-size:13px}th,td{padding:11px 12px;border-bottom:1px solid hsl(var(--border))}th{color:hsl(var(--muted-foreground));font-size:11px}.actions{white-space:nowrap}.actions button{margin-right:4px;font-size:11px}.empty{padding:44px;text-align:center;color:hsl(var(--muted-foreground))}.pagination{font-size:12px;color:hsl(var(--muted-foreground))}.pagination div{display:flex;gap:6px}.modal-backdrop{position:fixed;z-index:1000;inset:0;display:grid;place-items:center;padding:20px;background:rgb(0 0 0 / 42%)}.editor{width:min(900px,100%);max-height:90vh;overflow:auto;border:1px solid hsl(var(--border));border-radius:12px;padding:20px;background:hsl(var(--card))}@media(max-width:680px){.crm-workflow-page{padding:12px}}
</style>
